package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A person on a sheet: a name and a grade (A, B or C: the one in force on the sheet's today), the version of the stored person, how many statements
 *  have been taken of them, and the last one's due-total (null when n/a, or none taken) and date (the sheet's
 *  today then; null when none taken), the date they are retired from (null: not retired), and whether they are
 *  dated grades and their dated holds (their OPEN claims dated within one, not bound by a statement, count in no
 *  live total), and their own terms in days (null: none). */
public record Person(long id, String sheetId, String name, String grade, long version, int statementCount,
        BigDecimal statedTotal, LocalDate statementDate, LocalDate retiredFrom, Grades grades,
        Holds holds, Integer terms) {
}
package net.officefloor.hq.app.person;

/** Body of a person add or edit: who is making it, and the person's name and grade. An edit also
 *  names the version of the person it was made from (null: not checked), and the date its grade applies
 *  from (yyyy-mm-dd; null: the sheet's today). An add's grade applies from the beginning of time. The person's own terms are a whole
 *  number of days, "" for none (on an edit: clears them), or null when not given (on an edit: left as they are). */
public record PersonRequest(String user, String name, String grade, Long version, String gradeFrom, String terms) {
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person as the screen shows them, with their grade in force on the sheet's today, their statement count and
 *  the last statement's due-total (two decimals; null when n/a, or none taken) and date (yyyy-mm-dd; null when none
 *  taken), the date they are retired from (yyyy-mm-dd; null: not retired), whether they have any hold, their dated
 *  grades, earliest first (each from its from-date, yyyy-mm-dd; null: from the beginning of time), and their holds
 *  in the order they were put on (from- and to-date, yyyy-mm-dd; null: unbounded on that side), and their own terms in days (null: none). */
public record PersonResponse(long id, String name, String grade, long version, int statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeResponse> grades,
        List<HoldResponse> holds, Integer terms) {

    /** A grade given from a from-date (yyyy-mm-dd; null: from the beginning of time). */
    public record GradeResponse(String grade, String from) {
    }

    /** A hold from a from-date to a to-date (yyyy-mm-dd; null: unbounded on that side). */
    public record HoldResponse(String from, String to) {
    }

    public static PersonResponse from(Person p) {
        return new PersonResponse(p.id(), p.name(), p.grade(), p.version(), p.statementCount(),
                p.statedTotal() != null ? p.statedTotal().toPlainString() : null,
                p.statementDate() != null ? p.statementDate().toString() : null,
                p.retiredFrom() != null ? p.retiredFrom().toString() : null, p.holds().any(),
                p.grades().history().stream()
                        .map(g -> new GradeResponse(g.grade(), g.from() != null ? g.from().toString() : null)).toList(),
                p.holds().history().stream().map(h -> new HoldResponse(h.from() != null ? h.from().toString() : null,
                        h.to() != null ? h.to().toString() : null)).toList(), p.terms());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file. */
public class AuditPersonAdded {
    public void audit(@Val PersonRequest request, @Val Person person, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + person.sheetId() + " by=" + request.user()
                + " name=" + person.name() + " grade=" + person.grade()
                + (request.terms() != null && !request.terms().isEmpty() ? " terms=" + request.terms() : ""));
    }
}
package net.officefloor.hq.app.person;

import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored edit in the audit file; the person's own terms whenever the edit changes them: gives terms
 *  other than those the person had, or clears terms the person had (blank: cleared). */
public class AuditPersonEdited {
    public void audit(@Val PersonRequest request, @Val Person loaded, @Val PersonResponse saved, Audit audit) {
        Integer terms = request.terms() == null || request.terms().isEmpty() ? null : Integer.valueOf(request.terms());
        audit.record("PERSON_EDITED sheet=" + loaded.sheetId() + " by=" + request.user()
                + " name=" + saved.name() + " grade=" + saved.grade()
                + (request.terms() != null && !Objects.equals(terms, loaded.terms())
                        ? " terms=" + request.terms() : ""));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a name is required, the grade
 *  is one of A, B or C, the grade's from-date (optional) a real yyyy-mm-dd date, the terms (optional)
 *  blank or a whole number of days. Publishes the request with its name trimmed. */
public class ValidatePerson {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> body) throws InvalidPersonException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPersonException("Sign in before changing people.");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("A name is required.");
        }
        if (name.length() > 200) {
            throw new InvalidPersonException("A name is at most 200 characters.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be a date, yyyy-mm-dd.");
            }
        }
        String terms = request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.isEmpty() && !terms.matches("\\d{1,4}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank for none.");
        }
        body.set(new PersonRequest(request.user().trim(), name, grade, request.version(),
                gradeFrom.isEmpty() ? null : gradeFrom,
                terms == null || terms.isEmpty() ? terms : String.valueOf(Integer.parseInt(terms))));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveNewPerson {
    public void save(@PathVariable("sheetId") String sheetId, @Val PersonRequest request,
            PersonRepository repository, Out<Person> person) {
        person.set(repository.insert(sheetId.trim(), request.name(), request.grade(),
                request.terms() == null || request.terms().isEmpty() ? null : Integer.valueOf(request.terms())));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Apply the edit to the loaded person and store it, refused when the person has been saved since
 *  the version the edit was made from. The grade is recorded from the edit's from-date (the sheet's today
 *  when none was given), keeping the grades already recorded from other dates. The person's own terms are set when the edit gives
 *  them (cleared when given blank). */
public class SavePerson {
    public void save(@Val PersonRequest request, @Val Person loaded, PersonRepository repository,
            SheetRepository sheets, Out<PersonResponse> saved) throws StalePersonException {
        long from = request.version() == null ? loaded.version() : request.version();
        Person person = new Person(loaded.id(), loaded.sheetId(), request.name(), loaded.grade(), from + 1,
                loaded.statementCount(), loaded.statedTotal(), loaded.statementDate(), loaded.retiredFrom(),
                loaded.grades(), loaded.holds(), loaded.terms());
        if (!repository.update(person, from)) {
            throw new StalePersonException(loaded.name());
        }
        LocalDate gradeFrom = request.gradeFrom() != null ? LocalDate.parse(request.gradeFrom())
                : sheets.today(loaded.sheetId());
        repository.grade(person, request.grade(), gradeFrom);
        if (request.terms() != null) {
            repository.terms(person, request.terms().isEmpty() ? null : Integer.valueOf(request.terms()));
        }
        saved.set(PersonResponse.from(repository.find(loaded.sheetId(), loaded.id())));
    }
}
package net.officefloor.hq.app.person;

/** A person add or edit to a name another person on the sheet already has. */
public class DuplicatePersonNameException extends Exception {
    public DuplicatePersonNameException(String name) {
        super("The name " + name + " is already in use on this sheet.");
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleDuplicatePersonName {
    public void handle(@Parameter DuplicatePersonNameException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.CONFLICT));
    }
}
